/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_products_after_update` AFTER UPDATE ON `tb_products` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        table_description,
        product_id
    )
    VALUES (
        'tb_products',
        'Update',
        USER(),
        CONCAT(
            'Producto actualizado: "', NEW.name,
            '". SKU: ', NEW.SKU,
            ', Precio anterior: $', OLD.current_price,
            ', Precio nuevo: $', NEW.current_price,
            ', Stock anterior: ', OLD.current_stock,
            ', Stock nuevo: ', NEW.current_stock
        ),
        NEW.ID
    );
END */;;
