CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_2000_multinational_users`()
BEGIN

    DECLARE v_i INT DEFAULT 1;
    DECLARE v_base INT DEFAULT 0;

    DECLARE v_email VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_age INT;
    DECLARE v_country CHAR(2);

    SELECT IFNULL(MAX(ID),0)
    INTO v_base
    FROM tb_users;

    WHILE v_i <= 2000 DO

        CALL sp_generate_email(
            v_base + v_i,
            v_email
        );

        CALL sp_generate_nick(
            v_base + v_i,
            v_nick
        );

        CALL sp_generate_age(v_age);
        CALL sp_generate_country(v_country);

        INSERT INTO tb_users(
            email,
            nick,
            password,
            status
        )
        VALUES(
            v_email,
            v_nick,
            SHA2('123456',256),
            1
        );

        CALL sp_insert_person(
            LAST_INSERT_ID(),
            CONCAT('Nombre',v_i),
            CONCAT('Apellido',v_i),
            DATE_SUB(CURDATE(),INTERVAL v_age YEAR),
            IF(RAND()>0.5,'Hombre','Mujer'),
            v_country,
            b'1'
        );

        SET v_i = v_i + 1;

    END WHILE;

END ;;
